{
                                        'o_stat-green': state.qualification.gate_pass_rate !== null and state.qualification.gate_pass_rate !== undefined and state.qualification.gate_pass_rate >= 70,
                                        'o_stat-yellow': state.qualification.gate_pass_rate !== null and state.qualification.gate_pass_rate !== undefined and state.qualification.gate_pass_rate >= 40 and state.qualification.gate_pass_rate < 70,
